use std::collections::HashMap;
use std::f64::consts::PI;

/// Bit pattern for comparison, with every NaN folded to one value; -0 and
/// +0 stay distinct.
fn bits(x: f64) -> u64 {
    if x.is_nan() {
        f64::NAN.to_bits()
    } else {
        x.to_bits()
    }
}

/// Exact rows match bit for bit. On `t` rows (cos/sin/atan2, libm-dependent
/// in the last ulp) a value may differ by `TRIG_ULPS` units of roundoff of
/// its own group: rotation-coupled coordinates share one, any other quantity
/// is alone, and an angle's magnitude is at least a half turn as atan2 error
/// is absolute. A real sign, axis, index or order mistake still fails
/// (`mutations_are_detected`).
const TRIG_ULPS: f64 = 4.0;
const ANGLE_FLOOR: f64 = 180.0;

/// A group of `n` coordinates sharing one magnitude, or one angle in degrees.
#[derive(Clone, Copy)]
enum G {
    N(usize),
    Deg,
}
use G::{Deg, N};

const MAT: &[G] = &[N(1), N(1), Deg, N(1), N(1), N(1), N(1), N(1)];

fn magnitude(xs: &[f64]) -> f64 {
    xs.iter()
        .filter(|x| x.is_finite())
        .fold(0.0_f64, |a, x| a.max(x.abs()))
}

/// Compares one oracle row; a mismatch is recorded, not panicked, so the
/// same loop can prove that mutated inputs are rejected.
struct Check {
    trig: bool,
    label: String,
    inexact: usize,
    worst_ulps: f64,
    bad: Option<String>,
}

impl Check {
    fn new(row: &str, line_no: usize) -> Check {
        Check {
            trig: row.split(' ').nth(1) == Some("t"),
            label: format!("line {}: {}", line_no + 1, &row[..row.len().min(160)]),
            inexact: 0,
            worst_ulps: 0.0,
            bad: None,
        }
    }

    fn fail(&mut self, what: String) {
        if self.bad.is_none() {
            self.bad = Some(format!("{}: {what}", self.label));
        }
    }

    fn group_at(&mut self, actual: &[f64], expected: &[f64], floor: f64) {
        if actual.len() != expected.len() {
            return self.fail(format!("{actual:?} vs {expected:?}"));
        }
        let mag = magnitude(expected).max(magnitude(actual)).max(floor);
        for (&a, &e) in actual.iter().zip(expected) {
            if bits(a) == bits(e) {
                continue;
            }
            // A signed-zero mismatch is never a rounding difference.
            if self.trig && a.is_finite() && e.is_finite() && a != e {
                let ulps = (a - e).abs() / (mag.max(f64::MIN_POSITIVE) * f64::EPSILON);
                self.worst_ulps = self.worst_ulps.max(ulps);
                if ulps <= TRIG_ULPS {
                    self.inexact += 1;
                    continue;
                }
            }
            self.fail(format!("{a:?} != {e:?}"));
        }
    }

    fn v(&mut self, actual: &[f64], expected: &[f64]) {
        self.group_at(actual, expected, 0.0);
    }

    fn deg(&mut self, actual: f64, expected: f64) {
        self.group_at(&[actual], &[expected], ANGLE_FLOOR);
    }

    /// An angle read from the difference of two transformed points: their
    /// roundoff, relative to the coordinate magnitude, is amplified by
    /// `magnitude / |difference|` (a collapsed tangent is ill-conditioned).
    fn deg_cond(&mut self, actual: f64, expected: f64, cond: f64) {
        self.group_at(&[actual], &[expected], ANGLE_FLOOR * cond.max(1.0));
    }

    fn split(&mut self, actual: &[f64], expected: &[f64], groups: &[G]) {
        if actual.len() != expected.len() {
            return self.fail(format!("{actual:?} vs {expected:?}"));
        }
        let mut at = 0;
        for g in groups {
            match *g {
                N(n) => self.v(&actual[at..at + n], &expected[at..at + n]),
                Deg => self.deg(actual[at], expected[at]),
            }
            at += if let N(n) = *g { n } else { 1 };
        }
    }

    fn opt(&mut self, actual: Option<Vec<f64>>, expected: Option<Vec<f64>>, groups: &[G]) {
        match (actual, expected) {
            (Some(a), Some(e)) => self.split(&a, &e, groups),
            (None, None) => {}
            (a, e) => self.fail(format!("{a:?} vs {e:?}")),
        }
    }

    fn chain(&mut self, actual: &[ChainEntry], expected: &str) {
        let want: Vec<&str> = if expected == "-" {
            Vec::new()
        } else {
            expected.split(';').collect()
        };
        if actual.len() != want.len() {
            return self.fail(format!("{} entries, want {}", actual.len(), want.len()));
        }
        for (e, w) in actual.iter().zip(want) {
            let (m, p) = w.split_once('/').expect("mat/pivot");
            self.split(&mat_vec(Some(e.mat)).expect("mat"), &list(m), MAT);
            self.v(&e.pivot, &list(p));
        }
    }
}

fn hex(h: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(h, 16).expect("hex bits"))
}

fn list(token: &str) -> Vec<f64> {
    token.split(',').map(hex).collect()
}

fn maybe(token: &str) -> Option<Vec<f64>> {
    (token != "-").then(|| list(token))
}

fn mat(token: &str) -> Option<MotionMat> {
    maybe(token).map(|v| MotionMat {
        dx: v[0],
        dy: v[1],
        rot: v[2],
        sx: v[3],
        sy: v[4],
        op: v[5],
        ax: v[6],
        ay: v[7],
    })
}

fn mat_vec(m: Option<MotionMat>) -> Option<Vec<f64>> {
    m.map(|m| vec![m.dx, m.dy, m.rot, m.sx, m.sy, m.op, m.ax, m.ay])
}

fn pose(token: &str) -> Pose {
    let v = list(token);
    Pose {
        dx: v[0],
        dy: v[1],
        rot: v[2],
        sx: v[3],
        sy: v[4],
    }
}

/// `-` is undefined and `~` the empty string.
fn uid(token: &str) -> Option<&str> {
    match token {
        "-" => None,
        "~" => Some(""),
        u => Some(u),
    }
}

/// A sampled value: `u` (undefined) and `z` (`[]`) read as NaN.
fn sample(token: &str) -> f64 {
    if token == "u" || token == "z" {
        f64::NAN
    } else {
        hex(token)
    }
}

fn extras(token: &str) -> Vec<Option<&str>> {
    if token == "-" {
        return Vec::new();
    }
    token
        .split(';')
        .map(|e| if e == "!" { None } else { uid(e) })
        .collect()
}

fn weights(token: &str) -> Vec<f64> {
    if token == "-" {
        return Vec::new();
    }
    token.split(';').map(sample).collect()
}

fn table(token: &str) -> HashMap<&str, Pose> {
    if token == "-" {
        return HashMap::new();
    }
    token
        .split(';')
        .map(|e| {
            let (u, p) = e.split_once('=').expect("uid=pose");
            (u, pose(p))
        })
        .collect()
}

/// A deliberate mistake the comparison must catch.
#[derive(Clone, Copy, PartialEq, Debug)]
enum Mutation {
    None,
    /// Parent blend read as `100 - t`: A and B swapped.
    Blend,
    /// Extra weights read by position among kept extras, not original index.
    Index,
    /// `align` inverted.
    Align,
    /// Bounds centre x and y swapped.
    Axis,
    /// Path percent off by one.
    Percent,
    /// Tangent y and rotations negated.
    Sign,
    /// The B-parent dispatch ignored.
    Dispatch,
}

impl Mutation {
    fn blend(self, x: f64) -> f64 {
        [x, 100.0 - x][usize::from(self == Mutation::Blend)]
    }

    fn weights(self, ex: &[Option<&str>], w: &[f64]) -> Vec<f64> {
        if self != Mutation::Index {
            return w.to_vec();
        }
        let kept = |e: &Option<&str>| e.is_some_and(|u| !u.is_empty());
        ex.iter()
            .zip(w)
            .filter(|(e, _)| kept(e))
            .map(|(_, &w)| w)
            .collect()
    }

    fn uid_b(self, b: Option<&str>) -> Option<&str> {
        if self == Mutation::Dispatch {
            None
        } else {
            b
        }
    }

    fn rot(self, m: MotionMat) -> MotionMat {
        let mut m = m;
        if self == Mutation::Sign {
            m.rot = -m.rot;
        }
        m
    }

    fn chain(self, token: &str) -> Vec<ChainEntry> {
        if token == "-" {
            return Vec::new();
        }
        token
            .split(';')
            .map(|e| {
                let (m, p) = e.split_once('/').expect("mat/pivot");
                let p = list(p);
                ChainEntry {
                    mat: self.rot(mat(m).expect("chain mat")),
                    pivot: [p[0], p[1]],
                }
            })
            .collect()
    }
}

