#[derive(Default)]
struct Run {
    rows: usize,
    exact_rows: usize,
    inexact: usize,
    worst_ulps: f64,
    bad: Vec<String>,
}

fn run(m: Mutation) -> Run {
    let mut r = Run::default();
    for (line_no, row) in ORACLE.lines().enumerate() {
        let t: Vec<&str> = row.split(' ').collect();
        let mut c = Check::new(row, line_no);
        match t[0] {
            "wp" => {
                let ex = extras(t[5]);
                let got = weighted_parents_of(
                    uid(t[2]),
                    uid(t[3]),
                    m.blend(sample(t[4])),
                    &ex,
                    &m.weights(&ex, &weights(t[6])),
                );
                match (got, t[7]) {
                    (None, "-") => {}
                    (Some(parts), exp) if exp != "-" => {
                        let want: Vec<&str> = exp.split(';').collect();
                        if parts.len() != want.len() {
                            c.fail(format!("{} parts, want {}", parts.len(), want.len()));
                        } else {
                            for (p, w) in parts.iter().zip(want) {
                                let (u, wt) = w.rsplit_once(':').expect("uid:weight");
                                if p.uid != uid(u) {
                                    c.fail(format!("uid {:?}, want {u}", p.uid));
                                }
                                c.v(&[p.weight], &[hex(wt)]);
                            }
                        }
                    }
                    (g, e) => c.fail(format!("{g:?} vs {e}")),
                }
            }
            "bam" | "pcm" => {
                let ex = extras(t[5]);
                let w = m.weights(&ex, &weights(t[6]));
                let poses = table(t[7]);
                let blended = || {
                    blended_ancestor_mat(
                        uid(t[2]),
                        uid(t[3]),
                        m.blend(sample(t[4])),
                        &ex,
                        &w,
                        |u| poses.get(u).copied(),
                    )
                };
                if t[0] == "bam" {
                    c.opt(mat_vec(blended()), maybe(t[8]), MAT);
                } else {
                    let legacy = || m.chain(t[8]);
                    let out = parent_chain_mats(m.uid_b(uid(t[3])), blended, legacy);
                    c.chain(&out, t[9]);
                }
            }
            "fp" => {
                let (en, align) = (t[2] == "1", (t[6] == "1") != (m == Mutation::Align));
                let s = maybe(t[4]).map(|v| PathSample {
                    x: v[0],
                    y: v[1],
                    angle: v[2],
                });
                let centre = maybe(t[5]).map(|v| {
                    if m == Mutation::Axis {
                        [v[1], v[0]]
                    } else {
                        [v[0], v[1]]
                    }
                });
                let out =
                    apply_follow_path(mat(t[3]), s.filter(|_| en), centre, align, sample(t[7]));
                c.opt(mat_vec(out), maybe(t[8]), MAT);
            }
            "fpo" => {
                let len = hex(t[2]);
                let pct = sample(t[3]) + f64::from(u8::from(m == Mutation::Percent));
                match (follow_path_offset(pct, len), t[9]) {
                    (None, "-") => {}
                    (Some(off), exp) if exp != "-" => {
                        let pt = list(t[4]);
                        let tan = maybe(t[5]).map(|v| {
                            let y = [v[1], -v[1]][usize::from(m == Mutation::Sign)];
                            [v[0], y]
                        });
                        let centre = maybe(t[7]);
                        let target = mat(t[6])
                            .zip(centre.clone())
                            .map(|(mm, c)| (m.rot(mm), [c[0], c[1]]));
                        let chain = m.chain(t[8]);
                        let [p, q] = follow_path_points([pt[0], pt[1]], tan, target, &chain);
                        let angle = (q[1] - p[1]).atan2(q[0] - p[0]) * 180.0 / PI;
                        c.v(&[off], &[hex(exp)]);
                        let want = list(t[10]);
                        c.v(&p, &want[..2]);
                        // Coordinate scale: every input and output position.
                        let mut scale = magnitude(&[p[0], p[1], q[0], q[1], pt[0], pt[1]]);
                        scale = scale.max(magnitude(&centre.unwrap_or_default()));
                        for e in &chain {
                            scale = scale.max(magnitude(&e.pivot));
                        }
                        let d = ((q[0] - p[0]).powi(2) + (q[1] - p[1]).powi(2)).sqrt();
                        c.deg_cond(angle, want[2], if d > 0.0 { scale / d } else { 1.0 });
                    }
                    (g, e) => c.fail(format!("{g:?} vs {e}")),
                }
            }
            op => panic!("unknown oracle op {op}"),
        }
        r.rows += 1;
        r.exact_rows += usize::from(c.inexact == 0 && c.bad.is_none());
        r.inexact += c.inexact;
        r.worst_ulps = r.worst_ulps.max(c.worst_ulps);
        r.bad.extend(c.bad);
    }
    r
}

#[test]
fn generated_oracle_matches_javascript() {
    let r = run(Mutation::None);
    assert!(
        r.bad.is_empty(),
        "{} rows differ:\n{}",
        r.bad.len(),
        r.bad.join("\n")
    );
    assert_eq!(r.rows, 1090, "oracle row count");
    println!(
        "property transform oracle: {}/{} rows bit-exact, {} bounded values, worst {:.3} group ulps",
        r.exact_rows, r.rows, r.inexact, r.worst_ulps
    );
}

/// Every operation family appears in the oracle, with the interesting
/// shapes: each count is what the generator emits.
#[test]
fn oracle_covers_the_families_and_edges() {
    let count = |p: &str| ORACLE.lines().filter(|l| l.starts_with(p)).count();
    for (op, n) in [
        ("wp ", 110),
        ("bam ", 330),
        ("pcm ", 130),
        ("fp ", 260),
        ("fpo ", 260),
    ] {
        assert_eq!(count(op), n, "{op}");
    }
    let has = |p: &str, f: &dyn Fn(&[&str]) -> bool| {
        ORACLE
            .lines()
            .filter(|l| l.starts_with(p))
            .any(|l| f(&l.split(' ').collect::<Vec<_>>()))
    };
    let nan = "7ff8000000000000";
    let neg0 = "8000000000000000";
    assert!(
        has("wp ", &|t| t[6].split(';').any(|w| w == nan)),
        "NaN weight"
    );
    assert!(
        has("wp ", &|t| t[6].split(';').any(|w| w == neg0)),
        "-0 weight"
    );
    assert!(
        has("wp ", &|t| t[5].contains(";~;")),
        "empty uid in the middle"
    );
    assert!(has("wp ", &|t| t[5].contains("!")), "null extra entry");
    assert!(
        has("wp ", &|t| t[7].contains(":0")
            || t[7].contains(":8000000000000000")),
        "zero weight part"
    );
    assert!(
        has("bam ", &|t| t[8] == "-" && t[5] != "-"),
        "weighted None"
    );
    assert!(
        has("pcm ", &|t| t[3] != "-" && t[3] != "~" && t[9] != "-"),
        "B-parent chain"
    );
    assert!(
        has("fp ", &|t| t[5] == "-" && t[4] != "-" && t[2] == "1"),
        "missing bounds"
    );
    assert!(has("fp ", &|t| t[6] == "0" && t[4] != "-"), "align off");
    assert!(
        has("fp ", &|t| t[6] == "1" && t[4] != "-" && t[2] == "1"),
        "align on"
    );
    assert!(has("fpo ", &|t| t[9] == "-"), "zero length");
    assert!(has("fpo ", &|t| t[5] == "-" && t[9] != "-"), "no tangent");
}

/// Each deliberate mistake must make rows fail; the counts are measured on
/// this oracle.
#[test]
fn mutations_are_detected() {
    for (m, at_least) in [
        (Mutation::Blend, 172),
        (Mutation::Index, 64),
        (Mutation::Align, 86),
        (Mutation::Axis, 160),
        (Mutation::Percent, 82),
        (Mutation::Sign, 163),
        (Mutation::Dispatch, 84),
    ] {
        let failed = run(m).bad.len();
        println!("{m:?}: {failed} rows rejected");
        assert!(failed >= at_least, "{m:?} slipped through: {failed} rows");
    }
}

/// JavaScript coercion of the raw samples, outside the oracle rows.
#[test]
fn falsy_samples_read_as_zero() {
    for blend in [f64::NAN, 0.0, -0.0] {
        let p = weighted_parents_of(Some("A"), Some("B"), blend, &[Some("C")], &[f64::NAN])
            .expect("parts");
        assert_eq!(p.len(), 3);
        assert_eq!(bits(p[0].weight), bits(1.0), "A at full weight");
        assert_eq!(bits(p[1].weight), bits(0.0), "B at +0, not -0");
        assert_eq!(bits(p[2].weight), bits(0.0), "NaN extra reads +0");
    }
    assert!(weighted_parents_of(Some("A"), Some("B"), 50.0, &[], &[]).is_none());
    // Extras that all drop still take the weighted path (two parts).
    let p = weighted_parents_of(Some("A"), Some("B"), 50.0, &[Some("")], &[100.0]).expect("parts");
    assert_eq!(p.len(), 2);
    assert_eq!(follow_path_offset(f64::NAN, 100.0), Some(0.0));
    assert!(follow_path_offset(50.0, 0.0).is_none());
    assert!(follow_path_offset(50.0, f64::NAN).is_none());
}
